// webrtc for the vault worker. workers have no RTCPeerConnection, so this stands in for get-webrtc
// (what hyper-webrtc uses) and forwards everything to a real one in the page (page.js).
// the data still goes browser to browser over webrtc, only the short hop page <-> worker is added.
// it covers exactly what hyper-webrtc uses: the setup calls, onicecandidate, and its one negotiated data channel
const state = { next_id: 0, next_mid: 0, waiting: new Map(), peers: new Map() }
self.addEventListener('message', on_message)

module.exports = { RTCPeerConnection: make_peer, RTCIceCandidate: make_candidate }

function make_peer (options) {
  const id = state.next_id++
  const record = { peer: null, channel: null }
  const peer = {
    onicecandidate: null,
    localDescription: null,
    createDataChannel,
    createOffer: () => ask(id, 'create_offer'),
    createAnswer: () => ask(id, 'create_answer'),
    setLocalDescription,
    setRemoteDescription: description => ask(id, 'set_remote_description', description),
    addIceCandidate: candidate => ask(id, 'add_ice_candidate', candidate),
    close: () => tell(id, 'close')
  }
  record.peer = peer
  state.peers.set(id, record)
  tell(id, 'create', { iceServers: options?.iceServers })
  return peer

  async function setLocalDescription (description) { peer.localDescription = await ask(id, 'set_local_description', description) }
  function createDataChannel (label, channel_options) {
    record.channel = make_channel(id)
    tell(id, 'create_channel', label, channel_options)
    return record.channel
  }
}

function make_candidate (candidate) { return { ...candidate } } // plain data is all the page needs

function make_channel (id) {
  const listeners = { open: new Set(), message: new Set(), error: new Set(), close: new Set() }
  return {
    readyState: 'connecting',
    addEventListener: (type, fn) => listeners[type].add(fn),
    removeEventListener: (type, fn) => listeners[type].delete(fn),
    send: data => tell(id, 'send', data),
    close: () => tell(id, 'close_channel'),
    listeners
  }
}

function ask (id, op, ...args) {
  const mid = state.next_mid++
  self.postMessage({ type: 'rtc', data: { mid, id, op, args } })
  return new Promise((resolve, reject) => state.waiting.set(mid, { resolve, reject }))
}

function tell (id, op, ...args) { ask(id, op, ...args).catch(() => {}) }

function on_message (event) {
  const msg = event.data
  if (msg?.type === 'rtc-reply') return on_reply(msg.data)
  if (msg?.type === 'rtc-event') return on_event(msg.data)
}

function on_reply ({ mid, value, error }) {
  const waiting = state.waiting.get(mid)
  state.waiting.delete(mid)
  if (error) waiting?.reject(new Error(error))
  else waiting?.resolve(value)
}

// events of the real peer connection and data channel in the page
function on_event ({ id, type, data, ready_state }) {
  const record = state.peers.get(id)
  if (!record) return
  if (type === 'icecandidate') return record.peer.onicecandidate?.({ candidate: data })
  const channel = record.channel
  if (!channel) return
  channel.readyState = ready_state
  for (const fn of channel.listeners[type]) fn({ data })
  if (type === 'close') state.peers.delete(id)
}
